-- 种子故事《奶奶的蓝白花布》(由 scripts/extract_book.py 生成,id 固定为 1)
USE canger;
SET NAMES utf8mb4;
INSERT INTO stories (id,title,subtitle,theme,material_id,age_band,page_count,style,cover_illus,pages, edu_goals_summary,symbol_ids,source_type,ai_generated,status,published_at) VALUES (1,'奶奶的蓝白花布','白族扎染小绘本','扎染',NULL,'4-5',9,'水彩','images/books/zharan/p1.png','[{"page_no": 1, "type": "cover", "text": "", "goal_text": "", "goal_domains": [], "illus": "images/books/zharan/p1.png", "illus_prompt": ""}, {"page_no": 2, "type": "content", "text": "清晨，白族的小院真安静。\\n奶奶搬出一块**白白软软**的布，\\n笑着说：\\"今天，我们做蓝白花布吧！\\"", "goal_text": "感受祖孙相处的温暖", "goal_domains": ["社会"], "illus": "images/books/zharan/p2.png", "illus_prompt": ""}, {"page_no": 3, "type": "content", "text": "蓝颜色从哪里来？\\n原来是一种叫\\"板蓝根\\"", "goal_text": "认识植物染料（板蓝根）", "goal_domains": ["科学"], "illus": "images/books/zharan/p3.png", "illus_prompt": ""}, {"page_no": 4, "type": "content", "text": "奶奶教我把白布捏成**小揪揪**，\\n用皮筋扎得紧紧的。\\n这里扎一下，那里绑一下，\\n像在包一个个小糖果。", "goal_text": "动手体验\\"扎\\"的动作与节奏", "goal_domains": ["艺术"], "illus": "images/books/zharan/p4.png", "illus_prompt": ""}, {"page_no": 5, "type": "content", "text": "把扎好的布，\\n轻轻放进**蓝蓝的染缸**。\\n\\"咕嘟咕嘟\\"——\\n白布喝饱了蓝颜色。", "goal_text": "观察颜色\\"浸\\"进布里的变化", "goal_domains": ["科学"], "illus": "images/books/zharan/p5.png", "illus_prompt": ""}, {"page_no": 6, "type": "content", "text": "等呀等，奶奶说：\\"可以打开啦！\\"\\n我解开皮筋——\\n哇！白布变成了蓝底白花", "goal_text": "感受\\"蓝白\\"对比的色彩美", "goal_domains": ["艺术"], "illus": "images/books/zharan/p6.png", "illus_prompt": ""}, {"page_no": 7, "type": "content", "text": "你看，有的像小花，\\n有的像蝴蝶，有的像小星星。\\n每一块布的花纹都不一样", "goal_text": "欣赏扎染的多样纹样", "goal_domains": ["艺术"], "illus": "images/books/zharan/p7.png", "illus_prompt": ""}, {"page_no": 8, "type": "content", "text": "板蓝根是**植物**，\\n染出的颜色不会伤害小河和小草。\\n我们爱护大自然，\\n大自然也送我们美丽的蓝白花。", "goal_text": "懂得草木染环保、爱护自然", "goal_domains": ["社会", "科学"], "illus": "images/books/zharan/p8.png", "illus_prompt": ""}, {"page_no": 9, "type": "ending", "text": "我也想做一块蓝白花布，\\n送给最爱的人", "goal_text": "鼓励亲子/区域活动动手体验扎染", "goal_domains": ["延伸"], "illus": "images/books/zharan/p9.png", "illus_prompt": ""}]','[{"domain": "社会", "count": 2}, {"domain": "科学", "count": 3}, {"domain": "艺术", "count": 3}, {"domain": "延伸", "count": 1}]','[]','seed',0,'published',NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title), subtitle=VALUES(subtitle), age_band=VALUES(age_band), page_count=VALUES(page_count), cover_illus=VALUES(cover_illus), pages=VALUES(pages), edu_goals_summary=VALUES(edu_goals_summary);
